args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?directorLabel ?death1 ?death2 WHERE {
  VALUES ?film { dbr:The_Prince_and_the_Dancer dbr:The_Brown_Wallet }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:deathDate ?death1 . }
  OPTIONAL { ?director dbp:death_date ?death2 . }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?directorLabel ?death WHERE {
  VALUES ?film { dbr:The_Prince_and_the_Dancer dbr:The_Brown_Wallet }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:deathDate ?d1 . }
  OPTIONAL { ?director dbp:death_date ?d2 . }
  BIND(COALESCE(?d1, ?d2) AS ?death)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(LANG(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(LANG(?directorLabel) = 'en') }
}
ORDER BY ?death
LIMIT 1

